package org.efootballrevival.runtimeprobe;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.Locale;
public final class RuntimeDiagnostics{
 private static final String TAG="ui71-runtime-diagnostics";
 private static final String[] NAMES={"y08-kits-status.json","resource-presence-status.json","http-resource-status.json","mod-last-error.json","hook-arena-status.json","ui71-gateway-startup.json","v25-73-bootstrap-error.txt","mod-startup-status.json","select-team-status.json","noodle-hair-status.json","myleague-73-status.json","noodle-advertise-error.txt","ui71-gateway-error.txt"};
 private static String read(File file)throws Exception{try(InputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[2048];int n,remaining=10000;while(remaining>0&&(n=in.read(b,0,Math.min(b.length,remaining)))>0){out.write(b,0,n);remaining-=n;}return new String(out.toByteArray(),"UTF-8")+(remaining==0?"\n[truncated]":"");}}
 private static String collect(Context a){File tools=new File(a.getFilesDir(),"embedded-gateway/work/tools");StringBuilder out=new StringBuilder("UI7.6 runtime diagnostics\nNo save or player records included.\n");boolean any=false;for(String n:NAMES){File f=new File(tools,n);if(!f.isFile())continue;any=true;out.append("\n--- ").append(n).append(" ---\n");try{out.append(read(f));}catch(Exception e){out.append(e.getClass().getSimpleName()).append(": ").append(e.getMessage());}out.append('\n');}if(!any)out.append("\nNo diagnostic files yet. Try Enter Game once, then reopen this panel.\n");return out.toString();}
 public static void attach(Activity a,View panel){if(!(panel instanceof LinearLayout)||panel.findViewWithTag(TAG)!=null)return;Button b=new Button(a);b.setTag(TAG);b.setText("Runtime Diagnostics");b.setAllCaps(false);b.setTextColor(0xffe2f5ff);b.setBackgroundColor(0xff19354c);b.setMinHeight(Math.round(48*a.getResources().getDisplayMetrics().density));b.setOnClickListener(v->{b.setEnabled(false);new Thread(()->{String text=collect(a);a.runOnUiThread(()->{b.setEnabled(true);if(!a.isFinishing())show(a,text);});},"ReadModDiagnostics").start();});((LinearLayout)panel).addView(b,new LinearLayout.LayoutParams(-1,-2));}
 private static void show(Activity a,String text){ScrollView scroll=new ScrollView(a);TextView view=new TextView(a);int pad=Math.round(16*a.getResources().getDisplayMetrics().density);view.setPadding(pad,pad,pad,pad);view.setTextSize(12);view.setTextIsSelectable(true);view.setText(text);scroll.addView(view);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Runtime Diagnostics").setView(scroll).setNegativeButton("Close",null).setPositiveButton("Copy",(d,w)->{android.content.ClipboardManager cb=(android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE);if(cb!=null)cb.setPrimaryClip(ClipData.newPlainText("73 UI7.6 diagnostics",text));Toast.makeText(a,"Diagnostics copied",Toast.LENGTH_SHORT).show();}).create();dialog.show();ResponsiveUi.fit(a,dialog);}
}
